16	#include "base/base_types.h"
17	#include "autofuse_config/auto_fuse_config.h"
18	namespace att {
19	enum class TilingImplType {
20	  HIGH_PERF,
21	  MAX,
22	  AXES_REORDER,
23	  UNKNOWN,
24	};
25	
26	struct TilingCodeGenConfig {
27	  TilingImplType type;
28	  std::string path;
29	  std::string op_name;
30	  std::string tiling_data_type_name{"TilingData"};
31	  bool gen_extra_infos{false};
32	  bool gen_tiling_data{true};
33	  bool high_precision{true};
34	  bool enable_small_shape_strategy{false};
35	  bool enable_multicore_ub_tradeoff{false};
36	  bool enable_autofuse_pgo{false};
37	  int64_t pgo_step_max{16};
38	  bool enable_score_func{false};
39	  bool is_autofuse{false};
40	  bool is_inductor_scene{false};
41	  bool is_cube{false};
42	  // ub多核权衡策略里ub和多核的阈值
43	  bool do_variable_replace{true};
44	  // 临时配置，用于控制变量替换是否开关
45	  double ub_threshold{0.2};
46	  double corenum_threshold{0.4};
47	  bool cache_enabled_at_compile_time{false};  // 编译态缓存开关（默认关闭）
48	  ge::ForceTilingCaseResult force_tiling_case;
49	  int64_t force_schedule_result{-1L};
50	  std::string force_template_op_name;
51	  std::string Debug() const {
52	    std::stringstream ss;
53	    ss << "TilingCodeGenConfig[type(" << static_cast<int32_t>(type) << ")"
54	       << ", path(" << path << ")"
55	       << ", tiling_data_type_name(" << tiling_data_type_name << ")"
56	       << ", gen_extra_infos(" << gen_extra_infos << ")"
57	       << ", gen_tiling_data(" << gen_tiling_data << ")"
58	       << ", high_precision(" << high_precision << ")"
59	       << ", ub_threshold(" << ub_threshold << ")"
60	       << ", corenum_threshold(" << corenum_threshold << ")"
61	       << ", enable_small_shape_strategy(" << enable_small_shape_strategy << ")"
62	       << ", enable_multicore_ub_tradeoff(" << enable_multicore_ub_tradeoff << ")"
63	       << ", enable_autofuse_pgo(" << enable_autofuse_pgo << ")"
64	       << ", enable_score_func(" << enable_score_func << ")"
65	       << ", force_schedule_result(" << force_schedule_result << ")"
66	       << ", force_tiling_case(" << force_tiling_case.Debug() << ")"
67	       << "]";
68	    return ss.str();
69	  }
70	};
71	}  // namespace att
72	#endif  // ATT_GENERATOR_CONFIG_H
