23	bool IsUniqueGroups(const TilingModelInfo &all_model_infos) {
24	  std::unordered_set<size_t> asc_graphs;
25	  std::unordered_set<size_t> groups_ids;
26	  std::unordered_set<size_t> impl_graphs_ids;
27	  for (const auto &model_info : all_model_infos) {
28	    asc_graphs.insert(model_info.schedule_group_ident.asc_graph_id);
29	    groups_ids.insert(model_info.schedule_group_ident.group_id);
30	    impl_graphs_ids.insert(model_info.schedule_group_ident.impl_graph_id);
31	  }
32	  return (asc_graphs.size() == 1UL) && (groups_ids.size() == 1UL) && (impl_graphs_ids.size() == 1UL);
33	}
