55	af::Status TilingCodeGenerator::GenTilingCode(const std::string &op_type, const TilingModelInfo &model_infos,
56	                                              const TilingCodeGenConfig &config) {
57	  std::map<std::string, std::string> tiling_res;
58	  GE_ASSERT_SUCCESS(GenTilingCode(op_type, model_infos, config, tiling_res), "Gen tiling impl code failed.");
59	  ge::CodePrinter tiling_dumper;
60	  if (config.gen_tiling_data) {
61	    GE_ASSERT_TRUE(tiling_res.find(config.tiling_data_type_name) != tiling_res.end(),
62	                   "Generate tiling data [%s] failed.", config.tiling_data_type_name.c_str());
63	    tiling_dumper.AddLine(tiling_res.at(config.tiling_data_type_name));
64	    if (!config.path.empty()) {
65	      tiling_dumper.SaveToFile(EnsureTrailingSlash(config.path) + op_type + "_" + kDefaultTilingDataFileName);
66	    }
67	  }
68	  if (!config.path.empty()) {
69	    for (const auto &[key, value] : tiling_res) {
70	      tiling_dumper.Reset();
71	      if (key == kTilingHeadIdentify) {
72	        tiling_dumper.AddLine(value);
73	        tiling_dumper.SaveToFile(kDefaultTilingHeadFileName);
74	      } else if (!GetSplitHeaderFileName(key).empty()) {
75	        tiling_dumper.AddLine(value);
76	        tiling_dumper.SaveToFile(EnsureTrailingSlash(config.path) + GetSplitHeaderFileName(key));
77	      } else if ((key == config.tiling_data_type_name) || (key.find(kDefaultTilingDataTypeName) != std::string::npos)) {
78	        // doning nothing,在上面做过处理了
79	      } else {
80	        tiling_dumper.AddLine(value);
81	        tiling_dumper.SaveToFile(EnsureTrailingSlash(config.path) + op_type + "_" + key + "_" +
82	                                 kDefaultTilingFuncFileName);
83	      }
84	    }
85	  }
86	  return af::SUCCESS;
87	}
