122	inline std::unordered_map<std::string, std::string> GetCacheReuseInfo(
123	    const FusedParsedScheduleResult &fused_parsed_schedule_result) {
124	  std::unordered_map<std::string, std::string> cache_reuse_info;
125	  for (const auto &asc_graph_groups : fused_parsed_schedule_result) {
126	    for (const auto &schedule_results_groups : asc_graph_groups.second) {
127	      for (const auto &group_graphs : schedule_results_groups.second.groups_tiling_model_info) {
128	        const auto &model_infos = group_graphs.second;
129	        if (model_infos.empty()) {
130	          continue;
131	        }
132	        const auto &cur_ident = model_infos[0].schedule_group_ident;
133	        const auto &cur_prefix = cur_ident.GetGroupPrefix();
134	        const auto &reuse_schedule_group = model_infos[0].reuse_schedule_group;
135	        if (reuse_schedule_group && reuse_schedule_group->IsReuseGroup(cur_ident)) {
136	          const auto &reuse_ident = reuse_schedule_group->reuse_group_ident;
137	          const auto &reuse_prefix = reuse_ident.GetGroupPrefix();
138	          cache_reuse_info[cur_prefix] = reuse_prefix;
139	        }
140	      }
141	    }
142	  }
143	  return cache_reuse_info;
144	}
