146	inline void SaveVarRelationsInfo(
147	    VarRelations &var_relations, size_t asc_graph_id, size_t impl_graph_id,
148	    const std::map<size_t, std::map<size_t, std::map<std::string, af::Expression>>> &schedule_result_var_relations) {
149	  for (auto schedule_result_var_relation = schedule_result_var_relations.begin();
150	       schedule_result_var_relation != schedule_result_var_relations.end(); ++schedule_result_var_relation) {
151	    size_t dst_schedule_group_id = schedule_result_var_relation->first;
152	    const auto &dst_var_relations_from_src = schedule_result_var_relation->second;
153	    for (auto dst_var_relation_from_src = dst_var_relations_from_src.begin();
154	         dst_var_relation_from_src != dst_var_relations_from_src.end(); ++dst_var_relation_from_src) {
155	      size_t src_schedule_group_id = dst_var_relation_from_src->first;
156	      const auto &relations = dst_var_relation_from_src->second;
157	      if (!relations.empty()) {
158	        GELOGD("[VAR_RELATIONS] graph_id = [%u], result_id = [%u], dst_group_id = [%u], src_group_id = [%u]:",
159	               asc_graph_id, impl_graph_id, dst_schedule_group_id, src_schedule_group_id);
160	      }
161	      for (auto relation = relations.begin(); relation != relations.end(); ++relation) {
162	        GELOGD("[VAR_RELATIONS]     dst_var_name is [%s], src_var_expression_string is [%s]", relation->first.c_str(),
163	               af::SymbolicUtils::ToString(relation->second).c_str());
164	      }
165	    }
166	  }
167	  var_relations[asc_graph_id][impl_graph_id] = schedule_result_var_relations;
168	}
