181	af::Status TilingCodeGenerator::GenTilingCode(const std::string &op_type,
182	                                              const FusedParsedScheduleResult &fused_parsed_schedule_result,
183	                                              const TilingCodeGenConfig &config,
184	                                              std::map<std::string, std::string> &tiling_res) {
185	  TilingModelInfo all_model_infos;
186	  ScoreFuncs schedule_result_score_func;
187	  VarRelations var_relations;
188	  EnableGroupParallels enable_group_parallels;
189	  TensorIdSet workspace_tensor_id_set;
190	  size_t group_num = 0UL;
191	
192	  GE_ASSERT_SUCCESS(
193	      CollectModelInfosAndMetadata(fused_parsed_schedule_result, all_model_infos, group_num, schedule_result_score_func,
194	                                   var_relations, enable_group_parallels, workspace_tensor_id_set),
195	      "Collect model infos and metadata failed.");
196	  GE_ASSERT_TRUE(group_num != 0UL, "group num is zero of op type = %s.", op_type.c_str());
197	
198	  const bool is_uniq_group = (group_num == 1UL);
199	  if (is_uniq_group) {
200	    return GenTilingCode(op_type, all_model_infos, config, tiling_res);
201	  }
202	
203	  generated_headers_.clear();
204	  GenTilingHead(op_type, all_model_infos, config, tiling_res, enable_group_parallels);
205	  GELOGD("Got model infos size %zu of op type = %s.", all_model_infos.size(), op_type.c_str());
206	
207	  std::unordered_map<std::string, std::string> cache_reuse_info = GetCacheReuseInfo(fused_parsed_schedule_result);
208	  uint32_t cache_capacity = static_cast<uint32_t>(all_model_infos.size()) * 2;
209	  GE_ASSERT_SUCCESS(GenScheduleGroupTilingBodies(op_type, fused_parsed_schedule_result, config, cache_reuse_info,
210	                                                 cache_capacity, enable_group_parallels, tiling_res),
211	                    "Generate schedule group tiling bodies failed.");
212	
213	  GenTilingParams params = {op_type, all_model_infos, config, cache_reuse_info};
214	  GenTilingTailExtParams ext_params = {schedule_result_score_func, var_relations, enable_group_parallels,
215	                                       workspace_tensor_id_set};
216	  GenTilingTail(params, tiling_res, ext_params);
217	  GE_ASSERT_SUCCESS(TilingCodeGenImpl::FinishGeneratedHeaders(generated_headers_, config.tiling_data_type_name,
218	                                                              config.is_autofuse, tiling_res),
219	                    "Finish generated tiling headers failed.");
220	  return af::SUCCESS;
221	}
