274	af::Status TilingCodeGenerator::CollectModelInfosAndMetadata(
275	    const FusedParsedScheduleResult &fused_parsed_schedule_result, TilingModelInfo &all_model_infos, size_t &group_num,
276	    ScoreFuncs &schedule_result_score_func, VarRelations &var_relations, EnableGroupParallels &enable_group_parallels,
277	    TensorIdSet &workspace_tensor_id_set) {
278	  group_num = 0UL;
279	  for (const auto &asc_graph_models : fused_parsed_schedule_result) {
280	    for (const auto &impl_graph_groups : asc_graph_models.second) {
281	      const auto &parsed_result = impl_graph_groups.second;
282	      size_t asc_graph_id = parsed_result.asc_graph_id;
283	      size_t impl_graph_id = parsed_result.impl_graph_id;
284	      for (const auto &sub_graphs : impl_graph_groups.second.groups_tiling_model_info) {
285	        group_num++;
286	        all_model_infos.insert(all_model_infos.end(), sub_graphs.second.begin(), sub_graphs.second.end());
287	        GE_ASSERT_SUCCESS(
288	            GetWorkspaceTensorId(workspace_tensor_id_set, sub_graphs.second, asc_graph_id, impl_graph_id));
289	      }
290	      schedule_result_score_func[kModelInfoLevel::K_SCHEDULE_RESULT_LEVEL][asc_graph_models.first]
291	                                [impl_graph_groups.second.impl_graph_id] = impl_graph_groups.second.score_func;
292	      SaveVarRelationsInfo(var_relations, impl_graph_groups.second.asc_graph_id, impl_graph_groups.second.impl_graph_id,
293	                           impl_graph_groups.second.var_relations);
294	      enable_group_parallels[asc_graph_models.first][impl_graph_groups.second.impl_graph_id] =
295	          impl_graph_groups.second.enable_group_parallel;
296	    }
297	  }
298	  return af::SUCCESS;
299	}
