301	af::Status TilingCodeGenerator::GenScheduleGroupTilingBodies(
302	    const std::string &op_type, const FusedParsedScheduleResult &fused_parsed_schedule_result,
303	    const TilingCodeGenConfig &config, const std::unordered_map<std::string, std::string> &cache_reuse_info,
304	    uint32_t cache_capacity, const EnableGroupParallels &enable_group_parallels,
305	    std::map<std::string, std::string> &tiling_res) {
306	  GELOGD("[DFX] schedule_results count: %zu, op_type[%s]", fused_parsed_schedule_result.size(), op_type.c_str());
307	  for (auto &asc_graph : fused_parsed_schedule_result) {
308	    GELOGD("[DFX] asc_graph_id: %zu, results: %zu, op_type[%s]", asc_graph.first, asc_graph.second.size(),
309	           op_type.c_str());
310	    for (auto &result : asc_graph.second) {
311	      GELOGD("[DFX] got result(impl_graph_id): %zu, op_type[%s]", result.first, op_type.c_str());
312	      // 计算当前ScheduleResult中的Group个数
313	      size_t group_num = result.second.groups_tiling_model_info.size();
314	      for (auto &group_graphs : result.second.groups_tiling_model_info) {
315	        TilingCodeGenConfig cur_config = config;
316	        cur_config.tiling_data_type_name =
317	            group_graphs.second[0].schedule_group_ident.GetGroupPrefix() + kDefaultTilingDataTypeName;
318	        GenTilingParams params = {op_type, group_graphs.second, cur_config, cache_reuse_info};
319	        // 创建impl并设置Group个数
