                                      const TilingCodeGenConfig &config);

  /**
   * @brief 生成缓存初始化和查询代码
   * @param code_printer 代码打印器（函数体）
   * @param tiling_model_info Tiling模型信息
   * @param config 生成器配置
   * @return af::Status
   */
