 * 负责生成FixedSizeHashMap模板类和通用缓存函数
 */
class TilingCacheCodeGen {
 public:
  TilingCacheCodeGen() = default;
  virtual ~TilingCacheCodeGen() = default;

  /**
   * @brief 生成FixedSizeHashMap模板类定义
   * @param code_printer 代码打印器
